-- ==========================================================================
-- email_templates_brand.sql — Cloud Technology branded HTML for the two
-- sign-up emails stored in the email_templates table.
-- Idempotent: safe to run more than once (pure UPDATEs on key_name).
-- Run once on live phpMyAdmin (and locally) — bodies use the exact tokens
-- MailDispatcher receives from AuthController:
--   email_verification : name, link, logo_url, support_email, support_phone, footer_text, year
--   account_ready      : name, email, customer_id, login_url, logo_url, support_email, support_phone, footer_text, year
-- Statements are separated by split markers (helper-friendly).
-- ==========================================================================

-- SPLIT
UPDATE email_templates
SET is_active = 1,
    subject = 'Verify your email — Cloud Technology',
    body =
'<!doctype html>\n<html lang="en" style="margin:0;padding:0">\n<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="supported-color-schemes" content="light dark"><title>Cloud Technology</title></head>\n<body style="margin:0;padding:0;background:#f4f6f9;font-family:Arial,Helvetica,sans-serif;color:#1f2937">\n<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background:#f4f6f9"><tr><td align="center" style="padding:28px 12px">\n<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="max-width:560px">\n\t<tr><td align="center" style="padding:6px 0 18px">\n\t\t<img src="{{logo_url}}" width="52" height="52" alt="Cloud Technology" style="display:block;margin:0 auto 8px;border:0;border-radius:10px">\n\t\t<div style="font-size:19px;font-weight:bold;color:#12284f;letter-spacing:.2px">Cloud<span style="color:#2563eb"> Technology</span></div>\n\t\t<div style="font-size:11px;color:#7a8ba3;text-transform:uppercase;letter-spacing:2px;margin-top:3px">Domains · Hosting · Cloud</div>\n\t</td></tr>\n\t<tr><td>\n\t\t<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background:#ffffff;border:1px solid #e5e7eb;border-radius:12px">\n\t\t\t<tr><td style="height:5px;background:#2563eb;font-size:0;line-height:0">&nbsp;</td></tr>\n\t\t\t<tr><td align="center" style="padding:30px 30px 8px">\n\t\t\t\t<div style="width:64px;height:64px;line-height:64px;border-radius:50%;background:#eff6ff;text-align:center;font-size:30px">✉</div>\n\t\t\t</td></tr>\n\t\t\t<tr><td style="padding:14px 30px 24px;font-size:14px;line-height:1.65">\n\t\t\t\t<p style="margin:0 0 14px;font-size:18px;font-weight:bold;color:#12284f;text-align:center">Hi {{name}} — one last step</p>\n\t\t\t\t<p style="margin:0 0 8px">Please confirm your email address to activate your Cloud Technology account.</p>\n\t\t\t\t<p style="margin:0 0 22px;color:#6b7280">The link below works for the next hour and can be used only once.</p>\n\t\t\t\t<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation"><tr><td align="center">\n\t\t\t\t\t<a href="{{link}}" style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;font-weight:bold;font-size:15px;padding:13px 34px;border-radius:8px">Verify my email address</a>\n\t\t\t\t</td></tr></table>\n\t\t\t\t<p style="margin:20px 0 8px;color:#6b7280;font-size:12px">Button not working? Copy and paste this link into your browser:</p>\n\t\t\t\t<p style="margin:0 0 18px;font-size:12px;word-break:break-all"><a href="{{link}}" style="color:#2563eb">{{link}}</a></p>\n\t\t\t</td></tr>\n\t\t\t<tr><td style="padding:15px 30px;border-top:1px solid #eef0f3;background:#f9fafc;font-size:12px;color:#6b7280;line-height:1.7">Need help? Email <a href="mailto:{{support_email}}" style="color:#2563eb;text-decoration:none">{{support_email}}</a> or call <b style="color:#374151">{{support_phone}}</b><br>This is an automated message — replying directly to it will not reach support.</td></tr>\n\t\t</table>\n\t</td></tr>\n\t<tr><td align="center" style="padding:16px 12px 6px;font-size:11.5px;color:#8a97a8;line-height:1.7">© {{year}} {{footer_text}} — Cloud Technology · Dhaka, Bangladesh · cloudtechnologybd.net</td></tr>\n</table>\n</td></tr></table>\n</body>\n</html>'
WHERE key_name = 'email_verification';

-- SPLIT
UPDATE email_templates
SET is_active = 1,
    subject = 'Your account is ready — Cloud Technology',
    body =
'<!doctype html>\n<html lang="en" style="margin:0;padding:0">\n<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="supported-color-schemes" content="light dark"><title>Cloud Technology</title></head>\n<body style="margin:0;padding:0;background:#f4f6f9;font-family:Arial,Helvetica,sans-serif;color:#1f2937">\n<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background:#f4f6f9"><tr><td align="center" style="padding:28px 12px">\n<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="max-width:560px">\n\t<tr><td align="center" style="padding:6px 0 18px">\n\t\t<img src="{{logo_url}}" width="52" height="52" alt="Cloud Technology" style="display:block;margin:0 auto 8px;border:0;border-radius:10px">\n\t\t<div style="font-size:19px;font-weight:bold;color:#12284f;letter-spacing:.2px">Cloud<span style="color:#2563eb"> Technology</span></div>\n\t\t<div style="font-size:11px;color:#7a8ba3;text-transform:uppercase;letter-spacing:2px;margin-top:3px">Domains · Hosting · Cloud</div>\n\t</td></tr>\n\t<tr><td>\n\t\t<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background:#ffffff;border:1px solid #e5e7eb;border-radius:12px">\n\t\t\t<tr><td style="height:5px;background:#22c55e;font-size:0;line-height:0">&nbsp;</td></tr>\n\t\t\t<tr><td align="center" style="padding:30px 30px 8px">\n\t\t\t\t<div style="width:64px;height:64px;line-height:64px;border-radius:50%;background:#f0fdf4;text-align:center;font-size:30px;color:#16a34a;font-weight:bold">✓</div>\n\t\t\t</td></tr>\n\t\t\t<tr><td style="padding:14px 30px 24px;font-size:14px;line-height:1.65">\n\t\t\t\t<p style="margin:0 0 14px;font-size:18px;font-weight:bold;color:#12284f;text-align:center">Welcome aboard, {{name}}</p>\n\t\t\t\t<p style="margin:0 0 16px">Your email address <b>{{email}}</b> is now verified and your Cloud Technology account is active. Keep these login details safe:</p>\n\t\t\t\t<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation" style="background:#f9fafc;border:1px solid #eef0f3;border-radius:8px;margin:0 0 20px">\n\t\t\t\t\t<tr><td style="padding:14px 18px;font-size:13px;line-height:2">Customer ID: <b style="color:#12284f">{{customer_id}}</b><br>Email: <b style="color:#12284f">{{email}}</b></td></tr>\n\t\t\t\t</table>\n\t\t\t\t<table width="100%" cellpadding="0" cellspacing="0" border="0" role="presentation"><tr><td align="center">\n\t\t\t\t\t<a href="{{login_url}}" style="display:inline-block;background:#2563eb;color:#ffffff;text-decoration:none;font-weight:bold;font-size:15px;padding:13px 34px;border-radius:8px">Sign in to your account</a>\n\t\t\t\t</td></tr></table>\n\t\t\t\t<p style="margin:18px 0 0;color:#6b7280;font-size:12px">Ready to get started? Browse domains and complete your first purchase at cloudtechnologybd.net.</p>\n\t\t\t</td></tr>\n\t\t\t<tr><td style="padding:15px 30px;border-top:1px solid #eef0f3;background:#f9fafc;font-size:12px;color:#6b7280;line-height:1.7">Need help? Email <a href="mailto:{{support_email}}" style="color:#2563eb;text-decoration:none">{{support_email}}</a> or call <b style="color:#374151">{{support_phone}}</b><br>This is an automated message — replying directly to it will not reach support.</td></tr>\n\t\t</table>\n\t</td></tr>\n\t<tr><td align="center" style="padding:16px 12px 6px;font-size:11.5px;color:#8a97a8;line-height:1.7">© {{year}} {{footer_text}} — Cloud Technology · Dhaka, Bangladesh · cloudtechnologybd.net</td></tr>\n</table>\n</td></tr></table>\n</body>\n</html>'
WHERE key_name = 'account_ready';

-- SPLIT
-- Verify both templates replaced every branding token (optional check):
SELECT key_name, is_active,
       body LIKE '%{{logo_url}}%' AS has_logo,
       body LIKE '%{{support_email}}%' AS has_support
FROM email_templates
WHERE key_name IN ('email_verification', 'account_ready');
